-- Pins in the wrong state (Carter, 2026-11-26, after Dogpatch USA: "check
-- other closed parks for wrong pins too"). Found by testing every park's pin
-- against its own region (US state polygons from us-atlas, countries from
-- country-coder): 29 landed in another state, mostly a same-named town
-- elsewhere (Rocky Point in Kansas, Memphis' Incredible Pizza in Alaska, the
-- Wildwood piers outside St. Louis). Coordinates from Wikipedia where it has
-- the park; the rest are estimated from the park's address and are listed
-- under estimated pins in missing-parks.md. Matched by name; idempotent.
UPDATE parks SET lat = CASE name WHEN 'Columbia Gardens' THEN 46.0066 WHEN 'Doling Park' THEN 37.2459 WHEN 'Fantasy Farm Amusement Park' THEN 39.457 WHEN 'Fun Pier' THEN 38.9881 WHEN 'Nickel''s Midway Pier' THEN 38.994 WHEN 'Sportland Pier' THEN 38.9965 WHEN 'Kentucky Shores Family Fun Center' THEN 36.9905 WHEN 'Lakeside Park (Salem)' THEN 37.2964 WHEN 'Revere Beach (Suffolk)' THEN 42.4085 WHEN 'Rockaways'' Playland' THEN 40.5838 WHEN 'Rocky Point Park' THEN 41.6892 WHEN 'Sans Souci Park' THEN 41.214 WHEN 'Santa''s Village AZoosment Park' THEN 42.093 WHEN 'Silver Beach Amusement Park' THEN 42.1125 WHEN 'Uncle Bernie''s Amusement Park' THEN 26.1385 WHEN 'Utah Fun Dome' THEN 40.665 WHEN 'Vollmar''s Park' THEN 41.47 WHEN 'West Point Park' THEN 40.209 WHEN 'Deer Forest Fun Park' THEN 42.184 WHEN 'Castle Fun Center' THEN 41.36 WHEN 'Fast Lane Entertainment' THEN 36.265 WHEN 'Holly Springs Farm' THEN 31.825 WHEN 'Kiddieland' THEN 37.422 WHEN 'Mainstay Farm' THEN 32.46 WHEN 'Malibu Jack''s (Lafayette)' THEN 40.417 WHEN 'Memphis'' Incredible Pizza Company' THEN 35.096 WHEN 'Starland Sportsplex & Fun Park' THEN 42.122 WHEN 'Magic Harbor' THEN 33.6 WHEN 'Tom Foolerys Adventure Park' THEN 37.76 END, lon = CASE name WHEN 'Columbia Gardens' THEN -112.4642 WHEN 'Doling Park' THEN -93.2905 WHEN 'Fantasy Farm Amusement Park' THEN -84.412 WHEN 'Fun Pier' THEN -74.81 WHEN 'Nickel''s Midway Pier' THEN -74.804 WHEN 'Sportland Pier' THEN -74.8015 WHEN 'Kentucky Shores Family Fun Center' THEN -88.308 WHEN 'Lakeside Park (Salem)' THEN -80.0289 WHEN 'Revere Beach (Suffolk)' THEN -70.9925 WHEN 'Rockaways'' Playland' THEN -73.8166 WHEN 'Rocky Point Park' THEN -71.3675 WHEN 'Sans Souci Park' THEN -75.96 WHEN 'Santa''s Village AZoosment Park' THEN -88.296 WHEN 'Silver Beach Amusement Park' THEN -86.4875 WHEN 'Uncle Bernie''s Amusement Park' THEN -80.192 WHEN 'Utah Fun Dome' THEN -111.888 WHEN 'Vollmar''s Park' THEN -83.69 WHEN 'West Point Park' THEN -75.299 WHEN 'Deer Forest Fun Park' THEN -86.32 WHEN 'Castle Fun Center' THEN -74.276 WHEN 'Fast Lane Entertainment' THEN -94.16 WHEN 'Holly Springs Farm' THEN -94.493 WHEN 'Kiddieland' THEN -94.693 WHEN 'Mainstay Farm' THEN -97.36 WHEN 'Malibu Jack''s (Lafayette)' THEN -86.83 WHEN 'Memphis'' Incredible Pizza Company' THEN -89.854 WHEN 'Starland Sportsplex & Fun Park' THEN -70.86 WHEN 'Magic Harbor' THEN -78.975 WHEN 'Tom Foolerys Adventure Park' THEN -77.478 END WHERE name IN ('Columbia Gardens', 'Doling Park', 'Fantasy Farm Amusement Park', 'Fun Pier', 'Nickel''s Midway Pier', 'Sportland Pier', 'Kentucky Shores Family Fun Center', 'Lakeside Park (Salem)', 'Revere Beach (Suffolk)', 'Rockaways'' Playland', 'Rocky Point Park', 'Sans Souci Park', 'Santa''s Village AZoosment Park', 'Silver Beach Amusement Park', 'Uncle Bernie''s Amusement Park', 'Utah Fun Dome', 'Vollmar''s Park', 'West Point Park', 'Deer Forest Fun Park', 'Castle Fun Center', 'Fast Lane Entertainment', 'Holly Springs Farm', 'Kiddieland', 'Mainstay Farm', 'Malibu Jack''s (Lafayette)', 'Memphis'' Incredible Pizza Company', 'Starland Sportsplex & Fun Park', 'Magic Harbor', 'Tom Foolerys Adventure Park');
